query.query:
query Query($reportId: String!) {
  qualityReport(where: {id: {_eq: $reportId}}) {
    edges {
      node {
        subjectList{
          sampleSize
        }
        qualitySpecificationGroup {
          name
          specifications {
            edges {
              node {
                specification {
                  id
                  name
                  imageId
                  lowerBound
                  upperBound
                  usable
                  code
                  description
                  fileId
                  expectedValue
                  typeId
                  unit{
                    name
                  }
                  qualityChecks (where: {reportId: {_eq: $reportId}}) {
                    edges {
                      node {
                        id
                        complete
                        result
                        note
                        value
                        qualitySpecificationId
                        reportId
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

