transforms.post:
(
  ($isNilOrEmpty(result.lowerBound) ? $ ~> | result | {}, ['lowerBound'] | : $)
  .($isNilOrEmpty(result.upperBound) ? $ ~> | result | {}, ['upperBound'] | : $)
).
(
  $castBoolean:= function() 
  {result.typeId = "Boolean" and (result.expectedValue ~> $trim ~> $lowercase) = "true" ? $ ~> | result | {"expectedValue": true} |
  : result.typeId = "Boolean" and (result.expectedValue ~> $trim ~> $lowercase) = "false" ? $ ~> | result | {"expectedValue": false} |
  : result.typeId = "Boolean" ? $throw("Expected value is neither true or false")};


  $castNumber:= function(){
        $tryCatch(
          function($value){
            result.typeId = "Number" ? $ ~> | result | {"expectedValue": expectedValue ~> $trim ~> $number} |
          },
          function($err, $value){
            $throw("Expected value: " & $value & " is not a valid number.")
          }
        )(result.expectedValue).(
          $exists(result.lowerBound) and $exists(result.upperBound) ? result.lowerBound < result.expectedValue and result.expectedValue < result.upperBound ? $ :
          $throw("The Expected Value: " & result.expectedValue & " is not between the Lower Bound (" & result.lowerBound & ") and Upper Bound (" & result.upperBound & ")") :
          $exists(result.lowerBound) ? result.lowerBound < result.expectedValue ? $  : $throw("The Expected Value: " & result.expectedValue & " is not greater than the Lower Bound (" & result.lowerBound & ")") :
          $exists(result.upperBound) ? result.upperBound > result.expectedValue ? $  : $throw("The Expected Value: " & result.expectedValue & " is not lower than the Upper Bound (" & result.upperBound & ")") :
          $
        )
      };
  $validateRegex:= function(){
    (
      $tryCatch(
          function($reg) { 
            $eval("$match('', " & $reg & ")")
          },
          function($err, $reg) { 
            $throw($reg & " is not valid regex")
          }
        )(result.expectedValue);
        $
      )
    };

  result.typeId = "Number" ? $castNumber() :
  result.typeId = "Boolean" ? $castBoolean() :
  result.typeId = "Regex" ? $validateRegex()  : $

).result

